INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("アヤネ", 2, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", "2020/07/31 12:00:00", 24, 10046, 2, 24001, "2030/12/17 14:59:59", 0.0, 0.0, 102301, 0.0, 401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("アヤネ", 2, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", "2020/07/31 12:00:00", 24, 10046, 1, 24002, "2030/12/17 14:59:59", 0.0, 2.21, 102301, 0.0, 402);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("アヤネ", 2, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", "2020/07/31 12:00:00", 24, 10046, 2, 24003, "2030/12/17 14:59:59", 0.0, 0.0, 102301, 0.0, 403);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("アサヒ", 1, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", "2020/07/31 12:00:00", 24, 10046, 2, 24004, "2030/12/17 14:59:59", 0.0, 1.99, 192201, 0.0, 701);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("アサヒ", 2, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", "2020/07/31 12:00:00", 24, 10046, 1, 24005, "2030/12/17 14:59:59", 0.0, 2.21, 192201, 0.0, 702);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("アサヒ", 1, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", "2020/07/31 12:00:00", 24, 10046, 2, 24006, "2030/12/17 14:59:59", 0.0, 3.33, 192201, 0.0, 703);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("部員３", 2, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", "2020/07/31 12:00:00", 24, 10046, 2, 24007, "2030/12/17 14:59:59", 0.0, 0.0, 192301, 0.0, 801);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("部員３", 2, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", "2020/07/31 12:00:00", 24, 10046, 1, 24008, "2030/12/17 14:59:59", 0.0, 2.68, 192301, 0.0, 802);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("部員３", 2, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", "2020/07/31 12:00:00", 24, 10046, 2, 24009, "2030/12/17 14:59:59", 0.0, 0.0, 192301, 0.0, 803);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("", 1, "やった！", "2020/07/31 12:00:00", 24, 10046, 1, 24010, "2030/12/17 14:59:59", 0.0, 0.0, 192501, 0.0, 501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("", 1, "勝ったよ！", "2020/07/31 12:00:00", 24, 10046, 1, 24011, "2030/12/17 14:59:59", 0.0, 0.0, 192501, 0.0, 502);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("", 1, "いい調子！", "2020/07/31 12:00:00", 24, 10046, 1, 24012, "2030/12/17 14:59:59", 0.0, 0.0, 192501, 0.0, 503);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ミサト", 2, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", "2020/07/31 12:00:00", 24, 10046, 6, 24013, "2030/12/17 14:59:59", 0.0, 5.33, 113501, 0.0, 111);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ミサト", 2, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", "2020/07/31 12:00:00", 24, 10046, 1, 24014, "2030/12/17 14:59:59", 0.0, 6.85, 113501, 0.0, 112);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ミサト", 2, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", "2020/07/31 12:00:00", 24, 10046, 1, 24015, "2030/12/17 14:59:59", 0.0, 3.0, 113501, 0.0, 113);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ダイチ", 2, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", "2020/07/31 12:00:00", 24, 10046, 1, 24016, "2030/12/17 14:59:59", 0.0, 6.11, 192401, 0.0, 611);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ダイチ", 2, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", "2020/07/31 12:00:00", 24, 10046, 1, 24017, "2030/12/17 14:59:59", 0.0, 6.75, 192401, 0.0, 612);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ダイチ", 2, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", "2020/07/31 12:00:00", 24, 10046, 2, 24018, "2030/12/17 14:59:59", 0.0, 0.0, 192401, 0.0, 613);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ハツネ", 1, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", "2020/07/31 12:00:00", 24, 10046, 2, 24019, "2030/12/17 14:59:59", 0.0, 4.52, 113401, 0.0, 211);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ハツネ", 1, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", "2020/07/31 12:00:00", 24, 10046, 2, 24020, "2030/12/17 14:59:59", 0.0, 3.89, 113401, 0.0, 212);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ハツネ", 2, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", "2020/07/31 12:00:00", 24, 10046, 1, 24021, "2030/12/17 14:59:59", 0.0, 13.49, 113401, 0.0, 213);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("カヤ", 2, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", "2020/07/31 12:00:00", 24, 10046, 1, 24022, "2030/12/17 14:59:59", 0.0, 3.17, 106501, 0.0, 311);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("カヤ", 2, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", "2020/07/31 12:00:00", 24, 10046, 1, 24023, "2030/12/17 14:59:59", 0.0, 4.42, 106501, 0.0, 312);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("カヤ", 1, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", "2020/07/31 12:00:00", 24, 10046, 6, 24024, "2030/12/17 14:59:59", 0.0, 2.89, 106501, 0.0, 313);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("アヤネ", 3, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", "2020/07/31 12:00:00", 24, 10046, 4, 24025, "2030/12/17 14:59:59", 0.0, 3.71, 102301, 0.0, 421);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("アサヒ", 1, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", "2020/07/31 12:00:00", 24, 10046, 2, 24026, "2030/12/17 14:59:59", 0.0, 5.1, 192201, 0.0, 721);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("部員３", 3, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", "2020/07/31 12:00:00", 24, 10046, 1, 24027, "2030/12/17 14:59:59", 0.0, 4.34, 192301, 0.0, 821);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("", 1, "いい勝負だったよ\nまたやろうね", "2020/07/31 12:00:00", 24, 10046, 1, 24028, "2030/12/17 14:59:59", 0.0, 0.0, 192501, 0.0, 521);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ミサト", 2, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", "2020/07/31 12:00:00", 24, 10046, 1, 24029, "2030/12/17 14:59:59", 0.0, 5.62, 113501, -360.0, 101);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ミサト", 2, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", "2020/07/31 12:00:00", 24, 10046, 1, 24030, "2030/12/17 14:59:59", 0.0, 9.58, 113501, -360.0, 102);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ミサト", 2, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", "2020/07/31 12:00:00", 24, 10046, 2, 24031, "2030/12/17 14:59:59", 0.0, 0.0, 113501, -360.0, 103);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ミサト", 1, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", "2020/07/31 12:00:00", 24, 10046, 2, 24032, "2030/12/17 14:59:59", 0.0, 9.13, 113501, -360.0, 104);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ミサト", 2, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", "2020/07/31 12:00:00", 24, 10046, 1, 24033, "2030/12/17 14:59:59", 0.0, 8.27, 113501, -360.0, 105);
